        "install": "pip install pre-commit",
        "commands": [
          "pre-commit install",
          "pre-commit run --all-files"
        ]
      }
    },
    "dependencies": {
      "from_pyproject_toml": [
        "mcp>=1.13",
        "opentelemetry-api>=1.39.0",
